code.source:
#include <iostream>
using namespace std;

int main() {
    int* p = new int(5);
    cout << *p << endl;
    *p = *p + 1;
    cout << *p << endl;
    delete p;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int* a = new int[3]{1, 2, 3};
    for (int i = 0; i < 3; i++) {
        a[i] = a[i] * 10;
    }
    cout << a[0] << " " << a[1] << " " << a[2] << endl;
    delete[] a;
    return 0;
}

